from pathlib import Path
import sys,json,hashlib,subprocess,time,difflib,platform,math
import numpy as np,pandas as pd,scipy,matplotlib
B=Path('user/user-data/tmp/step26-fourth-revision-audit');O=B/'original/v27_cosmology_desi_bao_audit';R=B/'run'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def strict(p):return json.loads(p.read_text(),parse_constant=lambda x:(_ for _ in ()).throw(ValueError(x)))
x={'inventory':json.loads((B/'inventory.json').read_text()),'inputs':[],'manifests':{}}
for name in ['V27_cosmology_desi_bao_audit (3).zip','step26_desi_bao_planck_sne_rsd_bbn_nogo_en (4).pdf','step26_desi_bao_planck_sne_rsd_bbn_nogo_hu (4).pdf']:
 p=Path('user/workspace/uploads')/name;x['inputs'].append({'path':str(p),'bytes':p.stat().st_size,'sha256':sha(p)})
for p in O.glob('SHA256*'):
 a=[]
