def comp(a,b,path=''):
 if type(a)!=type(b):diffs.append({'path':path,'a_type':str(type(a)),'b_type':str(type(b))});return
 if isinstance(a,dict):
  if a.keys()!=b.keys():diffs.append({'path':path,'keys_original':list(a),'keys_run':list(b)})
  for k in a.keys()&b.keys():comp(a[k],b[k],path+'/'+k)
 elif isinstance(a,list):
  if len(a)!=len(b):diffs.append({'path':path,'length_original':len(a),'length_run':len(b)})
