 elif isinstance(a,(float,int)) and not isinstance(a,bool):
  assert math.isfinite(a) and math.isfinite(b)
  nums.append({'path':path,'original':a,'rerun':b,'abs_diff':abs(a-b),'rel_diff':abs((a-b)/a) if a else (0 if b==0 else None)})
 elif a!=b:diffs.append({'path':path,'original':a,'rerun':b})
comp(strict(O/'tal_hubble_desi_bao_summary.json'),strict(R/'tal_hubble_desi_bao_summary.json'))
x['JSON_comparison']={'numeric_fields':len(nums),'differences':diffs,'max_absolute':max(nums,key=lambda z:z['abs_diff']),'max_relative':max((z for z in nums if z['rel_diff'] is not None),key=lambda z:z['rel_diff']),'all_numeric_fields':nums}
x['CSV_comparisons']=[]
for p in sorted(O.glob('*.csv')):
 a=pd.read_csv(p);b=pd.read_csv(R/p.name);v={'file':p.name,'shape':list(a.shape),'same_shape':a.shape==b.shape,'same_columns':list(a.columns)==list(b.columns),'missingness_equal':bool(a.isna().equals(b.isna())),'numeric_cells_compared':0,'max_abs':0.,'max_rel':0.,'nonnumeric_differences':[]}
 assert v['same_shape'] and v['same_columns']
 for c in a:
  if pd.api.types.is_numeric_dtype(a[c]) and pd.api.types.is_numeric_dtype(b[c]):
   aa=a[c].to_numpy(dtype=float);bb=b[c].to_numpy(dtype=float);m=np.isfinite(aa)&np.isfinite(bb);d=abs(aa[m]-bb[m]);v['numeric_cells_compared']+=int(m.sum());v['max_abs']=max(v['max_abs'],float(max(d,default=0.)))
   m=m&(aa!=0);d=abs((aa[m]-bb[m])/aa[m]);v['max_rel']=max(v['max_rel'],float(max(d,default=0.)))
  elif not a[c].fillna('<NA>').astype(str).equals(b[c].fillna('<NA>').astype(str)):v['nonnumeric_differences'].append(c)
 x['CSV_comparisons'].append(v)
x['Markdown_differences']={}
for f in list(O.glob('*.md')):
 d=''.join(difflib.unified_diff(f.read_text().splitlines(True),(R/f.name).read_text().splitlines(True),fromfile='original',tofile='rerun'))
 x['Markdown_differences'][f.name]=d;(B/(f.stem+'.diff')).write_text(d)
