for lang in ['hu','en']:
 p=Path('user/workspace/uploads')/f'step26_desi_bao_planck_sne_rsd_bbn_nogo_{lang} (4).pdf';q=O/f'step26_desi_bao_planck_sne_rsd_bbn_nogo_{lang}.pdf'
 x['external_PDF_matches_archive'][lang]=p.read_bytes()==q.read_bytes()
x['PDF_mode_tests']=[]
for args in [['run_all.py','--pdf'],['compile_step26_clean_pdfs.py'],['compile_step26_clean_pdfs.py','--tex-only']]:
 z=subprocess.run([sys.executable,str(R/args[0]),*args[1:]],capture_output=True,text=True,timeout=60)
