(B/'reproduction.json').write_text(json.dumps(x,ensure_ascii=False,indent=2,allow_nan=False))
print(json.dumps({k:v for k,v in x.items() if k not in ['full_run','JSON_comparison','Markdown_differences','manifests']},indent=2,ensure_ascii=False))
print('manifests', {k:len(v) for k,v in x['manifests'].items()});print('run',p.returncode,'seconds',x['full_run']['elapsed_seconds'],'sources',len(before));print('JSON',len(nums),'maxabs',x['JSON_comparison']['max_absolute'],'maxrel',x['JSON_comparison']['max_relative'],'diffs',diffs)
